<script setup lang="ts">
import { computed, ref } from 'vue'
import { ROLES, usePmisStore, type Meeting } from '@/stores/pmis'
import plan from '@/data/assessmentPlan.json'
import { PARTS } from '@/data/parts'
const pm=usePmisStore()
const emit=defineEmits<{openTask:[code:string];openDocument:[code:string];openAsset:[id:string];openIssues:[]}>()
const blank=():Meeting=>({id:'',title:'',date:'',chair:'',attendees:'',agendaIds:[],minutes:'',decision:'',status:'草稿',confirmedBy:'',confirmedAt:''})
const draft=ref(blank()), selected=ref(false), notice=ref(''), failed=ref(false), reason=ref(''), search=ref('')
const current=computed(()=>pm.state.meetings.find(m=>m.id===draft.value.id))
const locked=computed(()=>current.value?.status==='已確認')
const meetings=computed(()=>pm.state.meetings.filter(m=>`${m.title} ${m.chair} ${m.attendees}`.includes(search.value)))
const action=ref({title:'',owner:'',due:'',description:'',task:'',asset:'',document:'',type:'會議行動',priority:'一般'})
function open(m?:Meeting){draft.value=m?JSON.parse(JSON.stringify(m)):blank();selected.value=true;notice.value='';reason.value='';action.value={title:'',owner:'',due:'',description:'',task:'',asset:'',document:'',type:'會議行動',priority:'一般'}}
function run(fn:()=>void){try{fn();failed.value=!!pm.error;notice.value=pm.error||'已儲存本機紀錄'}catch(e){failed.value=true;notice.value=e instanceof Error?e.message:'操作失敗'}}
function save(){draft.value.id=pm.saveMeeting(draft.value)}
function confirm(){save();pm.confirmMeeting(draft.value.id);draft.value=JSON.parse(JSON.stringify(current.value))}
function addAction(){const id=pm.addMeetingAction(draft.value.id,action.value);draft.value.agendaIds=[...new Set([...draft.value.agendaIds,id])];action.value={...action.value,title:'',description:''}}
function exportMinutes(){if(!current.value)return;const m=current.value;const body=[`# ${m.title}`,`日期：${m.date}｜主持：${m.chair}`,`出席：${m.attendees}`,`狀態：${m.status}（本機協作紀錄，非正式簽認）`,m.confirmedBy?`確認：${m.confirmedBy} ${m.confirmedAt}`:'', '## 討論紀錄',m.minutes,'## 決議',m.decision,'## 議題與行動',...m.agendaIds.map(id=>{const i=pm.state.issues.find(x=>x.id===id);return i?`- ${i.id} ${i.title}｜${i.owner}｜${i.due||'期限未定'}｜${i.status}\n  WBS ${i.task||'—'}／模型 ${i.asset||'—'}／文件 ${i.document||'—'}\n  ${i.description}`:''})].join('\n\n');const url=URL.createObjectURL(new Blob([body],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`meeting-${m.date}-${m.id.slice(0,8)}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><section class="meetings"><div class="top"><label>角色視角<select v-model="pm.role"><option v-for="r in ROLES" :key="r">{{r}}</option></select></label><label>操作人<input v-model="pm.actor" placeholder="輸入操作人姓名" /></label><button @click="open()">＋ 建立會議</button></div><p class="muted">本機會議與決策紀錄，不發送邀請、不代表正式簽認。議題結案由議題流程處理，確認會議不會自動結案。</p><p v-if="pm.error" class="error">{{pm.error}}</p><p v-if="notice" :class="failed?'error':'success'" role="status">{{notice}}</p><div class="layout"><aside><input v-model="search" placeholder="搜尋會議／主持／出席者" aria-label="搜尋會議" /><p v-if="!meetings.length">尚無符合條件的會議。</p><button v-for="m in meetings" :key="m.id" class="meeting-item" :class="{active:draft.id===m.id}" @click="open(m)"><b>{{m.title}}</b><small>{{m.date}} · {{m.status}}</small><small>{{m.chair}} · {{m.agendaIds.length}} 項議題</small></button></aside><div v-if="selected" class="editor"><h3>{{draft.id?'會議詳情':'新增協調會議'}}</h3><form @submit.prevent="run(save)"><fieldset :disabled="locked"><div class="grid"><label class="wide">會議名稱<input v-model="draft.title" required /></label><label>日期<input type="date" v-model="draft.date" required /></label><label>主持人<input v-model="draft.chair" required /></label><label class="wide">出席者與單位<textarea v-model="draft.attendees" placeholder="例如：業主 PMO、HPE 電力顧問、施工單位；填寫具名人員" /></label></div><details open><summary>選入議程的議題（{{draft.agendaIds.length}}）</summary><p v-if="!pm.state.issues.length">尚無議題，可先儲存草稿，再於下方建立行動項目。</p><label v-for="i in pm.state.issues" :key="i.id" class="check"><input type="checkbox" v-model="draft.agendaIds" :value="i.id" />{{i.id}} · {{i.title}} · {{i.status}}</label></details><label>討論紀錄<textarea v-model="draft.minutes" rows="4" /></label><label>決議、條件與待決事項<textarea v-model="draft.decision" rows="4" placeholder="記錄決定、適用條件；未達共識的事項也需明確保留" /></label><button>儲存草稿</button></fieldset></form><div class="actions"><button v-if="draft.id&&!locked" @click="run(confirm)">儲存並確認紀錄</button><button v-if="draft.id" @click="exportMinutes">匯出已儲存會議紀錄</button></div><template v-if="locked"><p>已由 {{current?.confirmedBy}} 於 {{current?.confirmedAt}} 確認。本機紀錄已鎖定編輯。</p><label>重新開啟原因<input v-model="reason" /></label><button @click="run(()=>{pm.reopenMeeting(draft.id,reason);draft=JSON.parse(JSON.stringify(current))})">重新開啟修訂</button></template><h3>議程與會後追蹤</h3><article v-for="id in draft.agendaIds" :key="id"><template v-for="i in pm.state.issues.filter(x=>x.id===id)" :key="i.id"><b>{{i.title}}</b><small>{{i.status}} · {{i.owner}} · {{i.due||'未設定期限'}}</small><p>{{i.description}}</p><p v-if="i.response">最近回覆：{{i.response}}</p><button v-if="i.task" @click="emit('openTask',i.task)">WBS {{i.task}}</button><button v-if="i.asset" @click="emit('openAsset',i.asset)">3D {{i.asset}}</button><button v-if="i.document" @click="emit('openDocument',i.document)">{{i.document}}</button></template></article><button v-if="draft.agendaIds.length" @click="emit('openIssues')">前往議題協調更新處理狀態</button><details v-if="draft.id&&!locked"><summary>＋ 建立會後行動項目</summary><form @submit.prevent="run(addAction)"><label>行動名稱<input v-model="action.title" required /></label><div class="grid"><label>責任人<input v-model="action.owner" required /></label><label>期限<input type="date" v-model="action.due" /></label><label>WBS<select v-model="action.task"><option value="">未關聯</option><option v-for="t in plan.tasks" :key="t.code" :value="t.code">{{t.code}} {{t.name}}</option></select></label><label>模型群組<select v-model="action.asset"><option value="">未關聯</option><option v-for="p in PARTS" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>交付文件<select v-model="action.document"><option value="">未關聯</option><option v-for="d in plan.documents" :key="d.code">{{d.code}}</option></select></label></div><label>行動內容與完成條件<textarea v-model="action.description" required /></label><button>建立並加入會議</button></form></details><details v-if="draft.id"><summary>會議異動紀錄</summary><article v-for="a in pm.state.audit.filter(a=>a.target===draft.id)" :key="a.id"><b>{{a.action}}</b><small>{{a.actor}} · {{a.at}}</small><p>{{a.note}}</p></article></details></div><div v-else class="empty"><h3>會議 → 決議 → 責任追蹤</h3><p>建立會議，選入待協調議題，再記錄出席者、討論與決議。會後行動會進入共用議題清冊，並可連回模型及交付文件。</p></div></div></section></template>
<style scoped>
.meetings{padding:16px;color:var(--text);font-size:12px;line-height:1.7}.top,.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:end}.layout{display:grid;grid-template-columns:190px minmax(0,1fr);gap:16px;margin-top:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.wide{grid-column:1/-1}label{display:flex;flex-direction:column;gap:5px;margin:10px 0}input,textarea,select,button{font:inherit;color:var(--text);background:var(--panel-solid);border:1px solid var(--line);border-radius:6px;padding:8px;min-width:0;max-width:100%;box-sizing:border-box}button{cursor:pointer;margin:3px}button:hover,.active{border-color:#55cfff;background:#55cfff15}textarea{resize:vertical;min-height:70px}.meeting-item{display:block;text-align:left;width:100%;padding:12px}.meeting-item b,small{display:block}small,.muted{color:var(--muted)}.error{color:#ffaaaa}.success{color:#76dcb1}.check{flex-direction:row}.check input{flex:none}fieldset{padding:0;border:0;min-width:0}fieldset:disabled{opacity:.7}article{border:1px solid var(--line);border-radius:8px;padding:10px;margin:10px 0}details{border-top:1px solid var(--line);padding:10px 0;margin:12px 0}summary{cursor:pointer;color:#8ad9ff}p{white-space:pre-wrap;overflow-wrap:anywhere}.empty{padding:25px}aside>input{width:100%}@media(max-width:1000px){.layout{grid-template-columns:1fr}aside{max-height:200px;overflow:auto}.grid{grid-template-columns:1fr}}
</style>
